/* ─────────────────────────────────────────────────────────────
   CONTACT
   The form has no backend, so it validates and then opens the
   visitor's email app with the message pre-filled (mailto:).
───────────────────────────────────────────────────────────── */
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function validate(f) {
  const e = {};
  if (f.name.trim().length < 2)       e.name    = "Please enter your name.";
  if (!EMAIL_RE.test(f.email.trim())) e.email   = "Please enter a valid email address.";
  if (f.subject.trim().length < 3)    e.subject = "Please add a short subject.";
  if (f.message.trim().length < 10)   e.message = "Your message should be at least 10 characters.";
  return e;
}

function Field({ id, label, error, children }) {
  return (
    <div className="field">
      <label htmlFor={`cf-${id}`}>{label}</label>
      {children}
      {error && <div className="err" id={`cf-${id}-err`}>{error}</div>}
    </div>
  );
}

function Contact() {
  const [form, setForm]     = useState({ name: "", email: "", subject: "", message: "" });
  const [errors, setErrors] = useState({});
  const [sent, setSent]     = useState(false);
  const [copied, setCopied] = useState(false);

  const set = (k) => (e) => {
    const v = e.target.value;
    setForm((f) => ({ ...f, [k]: v }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
    if (sent) setSent(false);
  };
  const aria = (k) => ({ "aria-invalid": errors[k] ? "true" : "false", "aria-describedby": errors[k] ? `cf-${k}-err` : undefined });

  const subjectText = `${form.subject.trim()} — message from ${form.name.trim()}`;
  const bodyText = `${form.message.trim()}\n\n—\n${form.name.trim()}\n${form.email.trim()}\n(Sent via portfolio contact form)`;
  const q = `subject=${encodeURIComponent(subjectText)}&body=${encodeURIComponent(bodyText)}`;
  const mailHref  = `mailto:${LINKS.email}?${q}`;
  const gmailHref = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(LINKS.email)}&su=${encodeURIComponent(subjectText)}&body=${encodeURIComponent(bodyText)}`;

  const handleSubmit = (e) => {
    e.preventDefault();
    const er = validate(form);
    setErrors(er);
    const first = Object.keys(er)[0];
    if (first) { document.getElementById(`cf-${first}`)?.focus(); return; }

    const a = document.createElement("a");
    a.href = mailHref;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setSent(true); setCopied(false);
  };

  const copyMessage = async () => {
    try { await navigator.clipboard.writeText(`To: ${LINKS.email}\nSubject: ${subjectText}\n\n${bodyText}`); setCopied(true); } catch { setCopied(false); }
  };

  const INFO = [
    { icon: "mail",     label: "Email",    value: LINKS.email,            href: `mailto:${LINKS.email}` },
    { icon: "linkedin", label: "LinkedIn", value: "sri-harshita-kondamuri", href: LINKS.linkedin, ext: true },
    { icon: "github",   label: "GitHub",   value: "Sriharshita05",         href: LINKS.github,   ext: true },
    { icon: "phone",    label: "Phone",    value: LINKS.phone,             href: `tel:${LINKS.phoneTel}` },
    { icon: "pin",      label: "Location", value: LINKS.location },
  ];

  return (
    <section id="contact" className="sec alt">
      <div className="wrap">
        <SecHead eyebrow="07 / Contact" title="Let's work together" />
        <div className="contact-grid">
          <Rev>
            <p className="about-p" style={{ fontSize: 17 }}>
              I'm actively looking for software developer opportunities where I can contribute, learn from a team and grow. If you have a role, an internship or a project in mind, I'd love to hear from you.
            </p>
            <div className="contact-list">
              {INFO.map((c) => {
                const inner = (<><span className="tile"><Icon name={c.icon} size={19} /></span><div><small>{c.label}</small><span>{c.value}</span></div></>);
                return c.href
                  ? <a key={c.label} className="contact-row" href={c.href} {...(c.ext ? { target: "_blank", rel: "noreferrer noopener" } : {})}>{inner}</a>
                  : <div key={c.label} className="contact-row">{inner}</div>;
              })}
            </div>
          </Rev>

          <Rev delay={100}>
            <form className="card form" onSubmit={handleSubmit} noValidate aria-label="Contact form">
              <h3>Send a message</h3>
              <div className="form-row">
                <Field id="name" label="Name" error={errors.name}>
                  <input id="cf-name" name="name" type="text" autoComplete="name" placeholder="Your name" value={form.name} onChange={set("name")} {...aria("name")} />
                </Field>
                <Field id="email" label="Email" error={errors.email}>
                  <input id="cf-email" name="email" type="email" autoComplete="email" placeholder="you@company.com" value={form.email} onChange={set("email")} {...aria("email")} />
                </Field>
              </div>
              <Field id="subject" label="Subject" error={errors.subject}>
                <input id="cf-subject" name="subject" type="text" placeholder="What is this about?" value={form.subject} onChange={set("subject")} {...aria("subject")} />
              </Field>
              <Field id="message" label="Message" error={errors.message}>
                <textarea id="cf-message" name="message" placeholder="Tell me about the opportunity…" value={form.message} onChange={set("message")} {...aria("message")} />
              </Field>
              <button type="submit" className="btn btn-primary" style={{ width: "100%" }}>Send Message <Icon name="send" size={16} /></button>
              <p className="form-note">Opens your email app, with Gmail and copy options if it doesn\u2019t.</p>
              <div role="status" aria-live="polite">
                {sent && (
                  <div className="form-ok">
                    <p>Your message is ready. If your email app didn't open, send it another way:</p>
                    <div className="form-ok-actions">
                      <a className="btn btn-secondary btn-sm" href={gmailHref} target="_blank" rel="noreferrer noopener">Open in Gmail <Icon name="external" size={14} /></a>
                      <a className="btn btn-secondary btn-sm" href={mailHref}>Open email app</a>
                      <button type="button" className="btn btn-secondary btn-sm" onClick={copyMessage}>{copied ? "Copied ✓" : "Copy message"}</button>
                    </div>
                    <p style={{ marginTop: ".6rem" }}>Or write directly to <a href={`mailto:${LINKS.email}`}>{LINKS.email}</a>.</p>
                  </div>
                )}
              </div>
            </form>
          </Rev>
        </div>
      </div>
    </section>
  );
}

