/* ─────────────────────────────────────────────────────────────
   APP
───────────────────────────────────────────────────────────── */
export default function Portfolio() {
  useEffect(() => {
    // Scroll via JS so in-page links also work inside sandboxed previews/iframes where hash navigation is blocked
    const onClick = (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a) return;
      const id = a.getAttribute("href").slice(1);
      const el = id && document.getElementById(id);
      if (!el) return;
      e.preventDefault();
      el.scrollIntoView({ behavior: "smooth", block: "start" });
      try { history.replaceState(null, "", `#${id}`); } catch { /* ignore */ }
    };
    document.addEventListener("click", onClick);
    return () => document.removeEventListener("click", onClick);
  }, []);

  useEffect(() => {
    document.title = "Sri Harshita Kondamuri — Full Stack Developer Portfolio";
    let m = document.querySelector('meta[name="description"]');
    if (!m) { m = document.createElement("meta"); m.name = "description"; document.head.appendChild(m); }
    m.content = "Portfolio of Sri Harshita Kondamuri, an aspiring full-stack developer and B.Tech CSE student skilled in React, Node.js, Laravel, MySQL and MongoDB.";
  }, []);

  return (
    <div>
      <style>{CSS}</style>
      <a href="#main" className="skip">Skip to content</a>
      <ScrollProgress />
      <Navbar />
      <main id="main">
        <Hero />
        <About />
        <Skills />
        <Projects />
        <Education />
        <Certifications />
        <Achievements />
        <Contact />
      </main>
      <Footer />
    </div>
  );
}